gojinjaPython Jinja2 <pre><code>{{ unset_var | default('fallback') }}             {# → fallback #}
{{ name      | default('Anonymous') }}            {# → name (if set) #}
{{ ""        | default('Anonymous', true) }}      {# → Anonymous #}
{{ 0         | default('—', true) }}              {# → — #}
</code></pre> <pre><code>&gt;&gt;&gt; tpl = env.from_string("{{ x | default('fallback') }}")
&gt;&gt;&gt; tpl.render()
'fallback'
&gt;&gt;&gt; tpl.render(x=None)        # None is defined; not Undefined
'None'
&gt;&gt;&gt; tpl = env.from_string("{{ '' | default('fallback', True) }}")
&gt;&gt;&gt; tpl.render()
'fallback'
</code></pre>
